# ════════════════════════════════════════════════════════════════════════════
# 2-STROKE DRAG / ENTHUSIAST CATALOG (April 20, 2026)
# ────────────────────────────────────────────────────────────────────────────
# Used at Aamby Valley + SE Asia drag scenes. Data sourced from Yamaha /
# Suzuki / Honda / Kawasaki service manuals and RD / RZ / RGV / NSR / KR /
# RS owner-community compiled databases. `stroke_type=2` flags the
# importer → uses 2T-specific expansion-chamber torque curve. `tuned_rpm`
# is where the expansion chamber comes "on pipe"; usually = peak_power_rpm.
# `powervalve=True` for bikes with YPVS / RC Valve / HPP / KIPS / ATAC —
# widens the usable band and softens hit-in-the-arse. Compression ratios
# are *corrected* (trapped) — 2T measured CR runs 11–13 but real CR after
# transfer-port loss is 6–8 which matches validator's widened 2T range.
# ════════════════════════════════════════════════════════════════════════════

